// 自動で作ったファイル。直すときは research_notes/占いシンガポール/中身_癖の型/癖の型_50.md を直して
// python -I types_js.py で作り直す。並び：型番号 = 日主×5 + 群 + 1（群：比劫0 食傷1 財2 官殺3 印4）
const TYPES=[{"n": 1,"stem": "Jia Wood","name": "The One Who Won't Lean on Anyone","zhStem": "甲木","zhName": "从不靠别人的人","line": "You'd rather stand alone in the wind than lean on someone. That backbone is your best part — used one notch too much, it means no one ever gets to hold you up.","zhLine": "你宁可一个人站在风里，也不愿靠别人。这根脊梁是你最好的地方——只是用多了一点，就再也没人能扶你一把。","inner": "If I have to ask for help, it's faster to just do it myself.","strength": "You keep going when others stop. People trust you because you don't fold.","stuck": {"Work": "you take the heaviest piece and never flag that it's too heavy.","Money": "you'd rather pay full price than ask a friend for a hand.","Love": "your partner can feel there's no room to be needed.","Family": "you're the child your parents never worry about — so no one asks how you are.","Self-worth": "needing help feels like losing."},"moves": ["If I catch myself thinking \"faster if I just do it\", then I'll hand one small piece to someone else that same day.","If someone offers to help this week, then I'll say \"yes, thank you\" before I say \"it's okay\".","If it's Sunday night, then I'll message one person one thing that was hard this week."]},{"n": 2,"stem": "Jia Wood","name": "The One Who Says What Everyone Was Thinking","zhStem": "甲木","zhName": "说出大家心里话的人","line": "You say the thing the room was thinking — and then you're the one left standing. Your honesty is a gift; used one notch too much, it lands before people are ready to hear it.","zhLine": "你说出了全场都在想的话——然后只剩你一个人站着。你的坦率是礼物，只是用多了一点，话就比别人准备好之前先到了。","inner": "I didn't say anything wrong. So why am I the one left standing out?","strength": "You see what's wrong early and you have the courage to name it. Teams improve because of you.","stuck": {"Work": "bosses hear the critique and miss the solution that came with it.","Money": "you start your own projects fast, before the numbers are clear.","Love": "you fix your partner's plan when they only wanted you to listen.","Family": "dinner-table debates with your parents that no one wins.","Self-worth": "after speaking up, you replay it for hours."},"moves": ["If I'm about to point out a problem in a meeting, then I'll start with one thing that's working.","If someone tells me about their plan, then I'll ask \"do you want ideas or just an ear?\" first.","If I feel the urge to send a sharp reply, then I'll wait until the next morning to send it."]},{"n": 3,"stem": "Jia Wood","name": "The One Who Keeps Building, Never Resting","zhStem": "甲木","zhName": "一直在建、从不停下的人","line": "You only feel okay when something is growing. That drive built everything you have — used one notch too much, a quiet weekend feels like falling behind.","zhLine": "只有在事情往上长的时候，你才觉得安心。这份冲劲撑起了你的一切——只是用多了一点，安静的周末都像在落后。","inner": "Every time I rest, I feel everyone else pulling ahead.","strength": "You turn plans into real things. You're the one who actually finishes the renovation, the course, the savings goal.","stuck": {"Work": "you add projects faster than you close them.","Money": "what you earn goes straight into the next build, with little left for you.","Love": "dates turn into planning sessions.","Family": "you show care by providing, and miss the moments that don't cost anything.","Self-worth": "your value feels tied to this month's progress."},"moves": ["If I open my to-do list on a weekend, then I'll close it and pick one thing to do just for fun.","If I'm about to start a new project, then I'll finish or drop one old one first.","If I'm with someone I love, then I'll put my phone face down for the first 30 minutes."]},{"n": 4,"stem": "Jia Wood","name": "The One Who Stands Straight Under Every Load","zhStem": "甲木","zhName": "什么重担都挺直腰扛的人","line": "You never bend, so people keep adding weight. Your reliability is real — used one notch too much, you hold up everyone's roof and forget your own.","zhLine": "你从来不弯腰，所以别人一直往你身上加重。你的可靠是真的——只是用多了一点，你撑起了所有人的屋顶，却忘了自己的。","inner": "If I fall apart, everything stops. So I can't.","strength": "You keep your word under pressure. When things get serious, people look for you.","stuck": {"Work": "the more you carry, the more gets handed to you.","Money": "you take the stable path long after it stopped fitting.","Love": "you show up as the dependable one and rarely as the tired one.","Family": "you're the one who handles the forms, the hospital visits, the BTO paperwork.","Self-worth": "you rate yourself by how much you can hold."},"moves": ["If a new task lands on my desk, then I'll ask \"what should I put down to take this?\"","If I'm asked \"you okay?\", then I'll answer with one honest sentence instead of \"fine\".","If I finish work on Friday, then I'll leave one evening this week with nothing scheduled."]},{"n": 5,"stem": "Jia Wood","name": "The One Who Waits Until They're Sure","zhStem": "甲木","zhName": "非要确定才动的人","line": "You want deep roots before you grow — so you keep watering the same spot. Your care is wise; used one notch too much, \"not yet\" becomes the answer every year.","zhLine": "你想先扎好根再往上长——所以一直在同一个地方浇水。你的谨慎是智慧，只是用多了一点，\"还不是时候\"就成了每一年的答案。","inner": "Once I'm a bit more ready... I said that last year too.","strength": "You think things through and rarely make careless moves. When you finally act, it holds.","stuck": {"Work": "you prepare for the promotion instead of asking for it.","Money": "savings sit still while you research the \"right\" option.","Love": "you wait to be sure of the other person before you show you care.","Family": "you check with your parents before decisions that are yours to make.","Self-worth": "you feel you need one more qualification to be enough."},"moves": ["If I've read three articles about the same decision, then I'll stop and write down what I'd choose today.","If I'm waiting for \"the right time\" on something small, then I'll do the first 10-minute step this week.","If I'm about to ask my parents' opinion, then I'll first write down my own answer."]},{"n": 6,"stem": "Yi Wood","name": "The One Who Goes Where the Group Goes","zhStem": "乙木","zhName": "跟着大家走的人","line": "You grow beautifully alongside others — so you rarely notice which way you'd grow alone. Your loyalty to your circle is real; used one notch too much, their choices quietly become yours.","zhLine": "你和身边的人一起长得很好——所以很少发现，一个人的话你会往哪里长。你对朋友的情义是真的，只是用多了一点，他们的选择就悄悄变成了你的。","inner": "If that's what everyone's doing, I guess it's fine for me too.","strength": "You build warm, lasting circles. People feel included around you.","stuck": {"Work": "you pick the path your friends picked.","Money": "group dinners, group trips, group gifts — your budget follows the chat.","Love": "friends' opinions of your partner weigh more than your own.","Family": "you compare your life stage with cousins at every reunion.","Self-worth": "you measure yourself by where your peers are."},"moves": ["If a group plan comes up in the chat, then I'll wait an hour and ask myself \"would I pick this alone?\"","If I catch myself comparing with a friend's post, then I'll write down one thing I want that they don't.","If I'm deciding something this week, then I'll decide before I ask anyone."]},{"n": 7,"stem": "Yi Wood","name": "The One Who Smooths Everything Over","zhStem": "乙木","zhName": "什么都圆过去的人","line": "You can talk your way around any wall, so you almost never have to say the hard thing. That grace is a talent — used one notch too much, the real issue never gets said.","zhLine": "你能绕过任何一堵墙，所以几乎不用说出难听的话。这份圆融是天赋，只是用多了一点，真正的问题就一直没被说出口。","inner": "I said it gently so no one would mind, and it didn't get through.","strength": "You read the mood and find words that keep everyone comfortable. You're the one who calms the group chat.","stuck": {"Work": "you soften feedback so much that nothing changes.","Money": "you agree to \"split later\" and never bring it up.","Love": "small things you never said pile up into one big silence.","Family": "you keep the peace between relatives and carry the leftover tension.","Self-worth": "you're liked, but you're not sure you're known."},"moves": ["If I'm about to say \"it's fine, no worries\", then I'll add one sentence of what I actually think.","If someone owes me money or a favour, then I'll send a friendly reminder this week.","If I notice I've rewritten a message three times to sound nicer, then I'll send the second version."]},{"n": 8,"stem": "Yi Wood","name": "The One Who Makes It Work for Everyone","zhStem": "乙木","zhName": "让每个人都满意的人","line": "You can always find the deal where everyone wins — except the version of you that wanted something different. Your resourcefulness is rare; used one notch too much, you're the one who bends the plan.","zhLine": "你总能找到让每个人都满意的办法——除了那个原本想要别的的你。你的灵活很难得，只是用多了一点，弯下去的总是你的计划。","inner": "Everyone's happy. ...What did I actually want again?","strength": "You make things happen through people. Deals close, schedules fit, families agree.","stuck": {"Work": "you take the shift, the client, the task nobody else could fit.","Money": "you pay for convenience to keep everyone happy.","Love": "you plan around your partner's schedule by default.","Family": "you're the one arranging festive visits so everyone's side is covered.","Self-worth": "being useful feels like the price of being wanted."},"moves": ["If someone asks \"what do you want to eat?\", then I'll name one place instead of \"anything\".","If I'm rearranging my week for someone, then I'll keep one slot that doesn't move.","If a plan is set this week, then I'll check: did I say what I wanted at least once?"]},{"n": 9,"stem": "Yi Wood","name": "The One Who Bends So No One Breaks","zhStem": "乙木","zhName": "弯下自己不让别人断的人","line": "You bend before anyone has to ask, so no one sees how far you've bent. Your flexibility keeps things together — used one notch too much, you forget which way is up for you.","zhLine": "别人还没开口，你就先弯下了腰，所以没人看到你弯了多少。你的柔软让一切不散——只是用多了一点，你就忘了自己往哪个方向长。","inner": "It's not worth saying no over, and meanwhile my days fill up.","strength": "You adapt under pressure. Bosses, in-laws and strict rules don't break you.","stuck": {"Work": "you adjust to every change and never ask for anything in return.","Money": "you accept the first offer because negotiating feels rude.","Love": "you shape yourself to what you think your partner expects.","Family": "your parents' plans for you quietly became your plans.","Self-worth": "you feel good only when no one is disappointed."},"moves": ["If I'm asked to take something on, then I'll say \"let me check and reply tomorrow\" before saying yes.","If I feel a small \"no\" inside, then I'll write it down even if I don't say it yet.","If I'm offered a deadline or price this week, then I'll ask one question about it before agreeing."]},{"n": 10,"stem": "Yi Wood","name": "The One Who Needs a Wall to Climb","zhStem": "乙木","zhName": "需要一面墙才肯往上爬的人","line": "You grow fast when someone is backing you — and wait when no one is. Knowing how to receive support is a strength; used one notch too much, your next step waits for someone else's yes.","zhLine": "有人撑着你的时候，你长得很快——没人撑的时候，你就停下来等。懂得接受支持是长处，只是用多了一点，你的下一步就要等别人点头。","inner": "If someone just said \"go for it\", I'd start right away.","strength": "You learn quickly from good mentors and you're grateful for help. People enjoy guiding you.","stuck": {"Work": "you wait for your manager to suggest the move you already want.","Money": "you follow advice from family on big money choices even when it doesn't fit.","Love": "you stay where it feels safe rather than where you grow.","Family": "leaving home feels like leaving support, so the BTO talk keeps getting pushed.","Self-worth": "your confidence rises and falls with other people's approval."},"moves": ["If I'm waiting for someone's permission on something small, then I'll start it and tell them after.","If I ask for advice this week, then I'll say what I'm leaning towards first.","If I get through a day without asking anyone, then I'll note one thing I decided myself."]},{"n": 11,"stem": "Bing Fire","name": "The One Who Always Treats Everyone","zhStem": "丙火","zhName": "总是请客的人","line": "You're the first to pay and the last to ask for anything back. Your generosity makes people feel warm — used one notch too much, your own needs never make it onto the bill.","zhLine": "你总是第一个买单，最后一个开口要回什么。你的大方让人觉得温暖——只是用多了一点，你自己的需要从来没出现在账单上。","inner": "Paying is easy. Saying I'm struggling isn't.","strength": "You lift the room. Friends remember you for showing up big.","stuck": {"Work": "you share credit so freely that your part gets missed.","Money": "treating friends and covering others leaves little for your own plans.","Love": "you give a lot and feel awkward when it comes back.","Family": "you're the one with the biggest ang bao, even when it stretches you.","Self-worth": "you feel worth it when you're giving, less so when you're resting."},"moves": ["If I reach for the bill this week, then I'll let someone else pay once.","If I'm asked \"what do you need?\", then I'll name one real thing.","If I spend on others this week, then I'll set aside the same small amount for my own plan."]},{"n": 12,"stem": "Bing Fire","name": "The One Who Can't Sit in a Quiet Room","zhStem": "丙火","zhName": "安静不下来的人","line": "You keep the room lit — the jokes, the plans, the next idea — so silence never gets a chance. That energy is magnetic; used one notch too much, you don't hear what the quiet was trying to tell you.","zhLine": "你让整个房间一直亮着——笑话、计划、下一个点子——安静从来没有机会出现。这份能量很迷人，只是用多了一点，你就听不到安静想告诉你的事。","inner": "When it's quiet, I can't settle.","strength": "You bring life to every group. Ideas move when you're in the room.","stuck": {"Work": "you start more than you can finish because starting is the fun part.","Money": "treats and little buys fill the gaps in your mood.","Love": "you entertain your partner instead of letting them see your low days.","Family": "you're the cheerful one at home, so serious talks get skipped.","Self-worth": "when you're not \"on\", you wonder if people still like you."},"moves": ["If I have a free evening, then I'll spend the first hour of it without a screen or a plan.","If I'm about to buy something small to feel better, then I'll wait 24 hours.","If I start a new idea this week, then I'll write down which old one it replaces."]},{"n": 13,"stem": "Bing Fire","name": "The One Who Promises More Than a Day Can Hold","zhStem": "丙火","zhName": "答应得比一天装得下还多的人","line": "You say yes with your whole heart, then do the maths at midnight. Your big-hearted ambition gets things moving — used one notch too much, your calendar pays the price.","zhLine": "你全心全意地答应，然后半夜才开始算。你的热情和野心让事情动起来——只是用多了一点，代价都落在你的日程表上。","inner": "I said I could do it. ...When exactly am I doing it?","strength": "You see opportunities and make them real. People bring you their best chances.","stuck": {"Work": "deadlines stack up because every offer felt too good to pass.","Money": "you spend now on the version of life you're building.","Love": "plans with your partner are the first thing to move when work grows.","Family": "you promise visits and help, then squeeze them in tired.","Self-worth": "you feel behind even while doing more than most."},"moves": ["If someone offers me something new, then I'll say \"let me look at my week\" before answering.","If my week is already full, then I'll move or cancel one thing before Wednesday.","If I make a promise this week, then I'll put it in my calendar right away with a real time."]},{"n": 14,"stem": "Bing Fire","name": "The One Who Shines So No One Worries","zhStem": "丙火","zhName": "发光让别人放心的人","line": "You're the sun everyone counts on, so you never get to be cloudy. Your warmth under pressure holds people together — used one notch too much, \"I'm fine\" becomes a job.","zhLine": "你是大家都靠着的太阳，所以你从来不能阴天。你在压力下的温暖把人都凝聚起来——只是用多了一点，\"我没事\"就成了一份工作。","inner": "If I'm not the cheerful one, everyone's stuck.","strength": "You lead from the front and keep morale up when it's hard.","stuck": {"Work": "you're the face of the team, so you absorb the pressure from above.","Money": "you keep up appearances — the right outfit, the right dinner.","Love": "your partner meets the bright you, rarely the tired you.","Family": "your parents see your success and not the cost of it.","Self-worth": "an off day feels like letting people down."},"moves": ["If someone asks how I am, then I'll answer with a real number from 1 to 10.","If I feel low one day this week, then I'll tell one person instead of hiding it.","If I'm leading something, then I'll ask someone else to open the next meeting."]},{"n": 15,"stem": "Bing Fire","name": "The One Who Waits to Be Invited","zhStem": "丙火","zhName": "要被邀请才出场的人","line": "You shine brightly once someone opens the door — and stand outside it until they do. Being thoughtful about your moment is wise; used one notch too much, you wait for a spotlight you could switch on yourself.","zhLine": "只要有人打开门，你就会发光——没人开门的时候，你就一直站在门外。懂得等时机是智慧，只是用多了一点，你就一直在等一盏你自己也能打开的灯。","inner": "If someone asked me, I'd really give it my all.","strength": "You learn deeply and bring warmth to what you study. When given a stage, you're excellent.","stuck": {"Work": "you wait to be picked for the project instead of asking.","Money": "you hold off on a side idea until someone says it's worth it.","Love": "you wait for the other person to make the first move.","Family": "you look for your parents' pride before trusting your own choice.","Self-worth": "you feel bright only when someone notices."},"moves": ["If there's a project I want, then I'll tell the person in charge by Friday.","If I'd like to see a friend, then I'll be the one to send the invite this week.","If I finish something good, then I'll share it once without waiting to be asked."]},{"n": 16,"stem": "Ding Fire","name": "The One Who Keeps the Lamp Lit Alone","zhStem": "丁火","zhName": "一个人守着灯的人","line": "You'd rather stay up guarding the flame than ask anyone to take a shift. Your devotion is quiet and strong — used one notch too much, you're the only one who knows how tired you are.","zhLine": "你宁可熬夜守着火，也不愿请别人换班。你的投入安静又有力——只是用多了一点，就只有你自己知道你有多累。","inner": "It's easier to do it myself than to explain.","strength": "You go deep and finish what others drop. Your work has care in every detail.","stuck": {"Work": "you become the only person who can do your job, so you can't take leave.","Money": "you'd rather spend your own time than pay or ask for help.","Love": "you keep your worries to yourself to protect your partner.","Family": "you handle things quietly and feel unseen for it.","Self-worth": "you judge yourself on what you carried, not on what you enjoyed."},"moves": ["If I'm doing a task only I know how to do, then I'll write the steps down for one other person.","If I'm worrying about something at night, then I'll tell one person about it the next day.","If someone offers a hand this week, then I'll give them one real piece of the work."]},{"n": 17,"stem": "Ding Fire","name": "The One Who Sees Every Flaw","zhStem": "丁火","zhName": "什么瑕疵都看得见的人","line": "You notice the typo, the off note, the thing nobody else caught — including in yourself. That eye for detail makes your work beautiful; used one notch too much, nothing ever feels finished.","zhLine": "别人没发现的错字、走音、小问题，你都看得见——包括你自己身上的。这份细心让你的作品很美，只是用多了一点，什么都觉得还没完成。","inner": "I can't send it yet. This part still bothers me.","strength": "Your standards make things better. People trust your eye.","stuck": {"Work": "you polish past the deadline, or comment on everyone's work.","Money": "you buy the better version to fix the small thing that bothers you.","Love": "you see your partner's small habits more than their big efforts.","Family": "your parents hear the correction more than the care behind it.","Self-worth": "one mistake outweighs ten things you did well."},"moves": ["If I've checked something twice, then I'll send it as it is.","If I'm about to point out a small flaw in someone's work, then I'll name one thing I like first.","If it's the end of the day, then I'll write down one thing I did that was good enough."]},{"n": 18,"stem": "Ding Fire","name": "The One Who Handles Everyone's Details","zhStem": "丁火","zhName": "替每个人顾好细节的人","line": "You remember the birthdays, the bills, the bookings — for everyone. Your care is precise and real; used one notch too much, you're managing lives that aren't yours to run.","zhLine": "生日、账单、订位——每个人的你都记得。你的照顾细致又真心，只是用多了一点，你就在管不属于你的人生。","inner": "If I don't do it, no one will even notice it needs doing.","strength": "You make things run smoothly. Your planning saves people money and stress.","stuck": {"Work": "you track everyone's tasks and get blamed when theirs slip.","Money": "you handle the shared accounts and quietly cover the gaps.","Love": "caring turns into checking — did you eat, did you pay, did you book.","Family": "you're the family's admin desk.","Self-worth": "you feel needed, but rarely looked after."},"moves": ["If I'm about to remind someone of their own task, then I'll let it go once and see what happens.","If I pay for something shared this week, then I'll ask for the split the same day.","If someone offers to plan the next outing, then I'll say yes and not fix their plan."]},{"n": 19,"stem": "Ding Fire","name": "The One Who Worries So Others Don't Have To","zhStem": "丁火","zhName": "替别人操心的人","line": "You think ahead about what could go wrong so others can relax. Your sense of responsibility is a light for people — used one notch too much, you carry worries that were never yours to hold.","zhLine": "你提前想好可能出错的地方，好让别人放松。你的责任感是别人的灯——只是用多了一点，你就扛起了本来不属于你的担心。","inner": "They say I overthink. But someone has to think it through.","strength": "You're prepared. When things go wrong, you already have a plan.","stuck": {"Work": "you over-check because you'd hate to let the team down.","Money": "you keep a large buffer and feel bad spending any of it.","Love": "you think through your partner's problems before they've finished telling you.","Family": "your parents' concerns become your nightly thinking.","Self-worth": "rest feels like you've stopped doing your part."},"moves": ["If I catch myself thinking \"what if\" after 10pm, then I'll write it on paper and leave it until morning.","If a worry belongs to someone else, then I'll ask them \"do you want my help with this?\" before stepping in.","If I have a free hour this week, then I'll spend it on something I enjoy that costs nothing, without checking my phone for work."]},{"n": 20,"stem": "Ding Fire","name": "The One Who Thinks It Through One More Time","zhStem": "丁火","zhName": "再想一遍的人","line": "You want to understand before you move, so you think it through once more — and once more. That depth is your gift; used one notch too much, the moment passes while you're still thinking.","zhLine": "你想先弄明白再动，所以再想一遍——又一遍。这份深度是你的天赋，只是用多了一点，时机就在你还在想的时候过去了。","inner": "I want to understand it properly first. ...I still don't.","strength": "You see layers other people miss. Your decisions are rarely careless.","stuck": {"Work": "you research the job move instead of applying.","Money": "you study investing for years and keep the money parked.","Love": "you analyse a message for an hour before replying.","Family": "you think about having the talk with your parents more than having it.","Self-worth": "you feel you don't know enough yet to have a say."},"moves": ["If I've been thinking about a decision for more than a week, then I'll set a date to decide by.","If I'm drafting a reply in my head, then I'll send it within 10 minutes.","If I learn something this week, then I'll try one small part of it the next day."]},{"n": 21,"stem": "Wu Earth","name": "The One Everyone Leans On","zhStem": "戊土","zhName": "大家都靠、自己不靠人的人","line": "Everyone leans on you, and you lean on no one. Being solid is your best quality — used one notch too much, mountains don't get asked if they're tired.","zhLine": "大家都靠着你，而你谁也不靠。稳是你最好的地方——只是用多了一点，从来没人问一座山累不累。","inner": "People think I'm the one who's fine. Maybe I make sure they do.","strength": "You're steady in a crisis. People feel safe with you.","stuck": {"Work": "you're the go-to for problems, so your own goals wait.","Money": "you lend or cover for friends and don't bring it up.","Love": "your partner may not know what you need, because you never say.","Family": "you're the eldest in spirit, even if not in age.","Self-worth": "being strong is how you feel worth something."},"moves": ["If someone brings me a problem this week, then I'll ask \"what have you tried?\" before I solve it.","If I'm owed money or a favour, then I'll mention it once, kindly.","If I feel heavy one evening, then I'll tell someone \"today was a lot\" instead of nothing."]},{"n": 22,"stem": "Wu Earth","name": "The One Who Knows the Better Way","zhStem": "戊土","zhName": "总知道更好做法的人","line": "You can see the better way to do it, so you take over before anyone asks. Your practical wisdom is real — used one notch too much, people stop trying around you.","zhLine": "你看得出更好的做法，所以别人还没开口你就接手了。你的实用智慧是真的——只是用多了一点，身边的人就不再尝试了。","inner": "I can't watch this. Here, let me do it.","strength": "You make things work and you teach well. Your methods last.","stuck": {"Work": "your team waits for you to fix it, so you never get time to grow.","Money": "you DIY everything, even when your time is worth more.","Love": "your partner feels corrected when you meant to help.","Family": "you redo your parents' or siblings' tasks \"properly\".","Self-worth": "you feel useful mostly when you're fixing."},"moves": ["If I see someone doing a task \"the slow way\", then I'll leave it unless they ask.","If I'm about to take over, then I'll ask \"want a tip or want me to do it?\"","If someone finishes something their way this week, then I'll thank them without adding a fix."]},{"n": 23,"stem": "Wu Earth","name": "The One Who Holds On, Just in Case","zhStem": "戊土","zhName": "什么都留着以防万一的人","line": "You keep the savings, the spare, the backup plan — just in case. Your steadiness with what you have protects people; used one notch too much, \"just in case\" stops you from living now.","zhLine": "存款、备用、后备方案，你都留着——以防万一。你守住手上东西的稳，保护了很多人，只是用多了一点，\"以防万一\"就让你没法活在现在。","inner": "Spending it now feels like a waste.","strength": "You build security slowly and well. People can count on your resources.","stuck": {"Work": "you stay in a role because it's safe, not because it fits.","Money": "you rarely spend on yourself, even when you can.","Love": "you hold back on plans because of what they might cost.","Family": "you're the safety net and feel you can't step away from it.","Self-worth": "your sense of safety depends on the number in the account."},"moves": ["If I'm keeping something nice \"for a special day\", then I'll use it this week.","If I'm saying \"maybe next year\", then I'll pick a month for it now.","If I'm keeping something \"just in case\", then I'll let go of one item I haven't used in a year."]},{"n": 24,"stem": "Wu Earth","name": "The One Who Never Leaves the Post","zhStem": "戊土","zhName": "从不离开岗位的人","line": "You stay at your post long after others have gone home. Your sense of duty is unshakeable — used one notch too much, you guard a place you might have outgrown.","zhLine": "别人都回家了，你还守在岗位上。你的责任感坚不可摧——只是用多了一点，你守着的可能是一个你早已长大离开的地方。","inner": "If I quit, I'll let people down. So, a little longer.","strength": "You're loyal and steady. Organisations run because of people like you.","stuck": {"Work": "you put in years of loyalty and wait for it to be noticed.","Money": "you don't negotiate because asking feels disloyal.","Love": "work duties come before your plans together.","Family": "you carry family duties without question, even when it's too much.","Self-worth": "you feel good only when you've done your duty."},"moves": ["If I'm staying late again, then I'll pick one evening this week to leave on time.","If my review or pay talk is coming, then I'll write down three things I did this year.","If I'm asked to cover for someone, then I'll say yes only if I can name what I'll drop."]},{"n": 25,"stem": "Wu Earth","name": "The One Who Waits for Solid Ground","zhStem": "戊土","zhName": "等地面够稳才迈步的人","line": "You only step when the ground feels completely solid. That caution has kept you safe — used one notch too much, you stand still while the path you wanted moves on.","zhLine": "你只在地面完全踏实的时候才迈步。这份谨慎一直保护着你——只是用多了一点，你站着不动，而你想走的路已经往前走了。","inner": "Once things are more certain. Until then, I'll stay as I am.","strength": "You make careful, lasting decisions. You rarely need to undo them.","stuck": {"Work": "you wait for certainty before applying or switching.","Money": "you keep money in one safe place for years.","Love": "you need a lot of reassurance before committing.","Family": "your parents' comfort zone becomes yours.","Self-worth": "you feel ready only when everything is in place."},"moves": ["If I'm waiting for \"the right time\", then I'll write down what \"ready\" actually looks like.","If I'm curious about something new, then I'll try it once this week in the smallest form.","If I feel stuck, then I'll ask one person who has done it, not one who would worry about it."]},{"n": 26,"stem": "Ji Earth","name": "The One Who Compares Quietly","zhStem": "己土","zhName": "暗暗比较的人","line": "You never say it out loud, but you know exactly where your friends are — the flat, the title, the ring. Your awareness of others keeps you grounded; used one notch too much, their timeline becomes your measuring stick.","zhLine": "你从来不说出口，但你很清楚朋友们走到哪一步了——房子、职位、戒指。你对身边的人很敏锐，这让你踏实，只是用多了一点，别人的进度就成了量你的尺。","inner": "I'm not in a hurry. ...But everyone else is moving on.","strength": "You're loyal to your people and you grow well in good company.","stuck": {"Work": "you choose based on what's respectable among peers.","Money": "you match your friends' spending to stay in step.","Love": "you feel your relationship should be \"at the same stage\" as others'.","Family": "reunions turn into quiet scorekeeping.","Self-worth": "you feel on track only when you're not behind someone."},"moves": ["If I scroll past a friend's big news and feel a pinch, then I'll write down one thing in my life I'm glad about.","If I'm about to spend to keep up with a group, then I'll ask myself \"would I buy this if no one saw it?\"","If someone asks about my plans this week, then I'll answer with my own timeline, not anyone else's."]},{"n": 27,"stem": "Ji Earth","name": "The One Who Feeds Everyone First","zhStem": "己土","zhName": "总先喂饱别人的人","line": "You make sure everyone has eaten before you sit down. Your nurturing is the warmest thing about you — used one notch too much, you eat last, and sometimes not at all.","zhLine": "你总要确认大家都吃饱了，自己才坐下。你的照顾是你最温暖的地方——只是用多了一点，你总是最后吃，有时根本没吃。","inner": "If everyone's having fun, that's enough. ...What about me?","strength": "You create comfort. Homes, teams and friendships feel better because of what you make.","stuck": {"Work": "you do the extra (the slides, the snacks, the onboarding) that no one counts.","Money": "you spend on hosting and gifts more than on your own needs.","Love": "you give care easily and find it hard to receive it.","Family": "you're the one who cooks, cleans up and checks on everyone.","Self-worth": "you feel worthy when you're useful to someone."},"moves": ["If I'm hosting or helping this week, then I'll sit down and eat with everyone, not after.","If someone offers to do something for me, then I'll say \"thank you\" and let them.","If I have one free hour, then I'll make or do something only for myself."]},{"n": 28,"stem": "Ji Earth","name": "The One Who Counts Every Dollar Twice","zhStem": "己土","zhName": "每一块钱都算两遍的人","line": "You know where every dollar went, and you check again before bed. Being careful with money is a real strength — used one notch too much, every small spend comes with a small weight.","zhLine": "你知道每一块钱去了哪里，睡前还要再算一遍。对钱谨慎是真本事——只是用多了一点，每一笔小花费都带着一点重量。","inner": "Did I really need this?","strength": "You manage resources well. Your household and projects stay on budget.","stuck": {"Work": "you take on extra work for extra income and leave no room to rest.","Money": "you rarely enjoy what you've saved for.","Love": "money talks with your partner become tense, even small ones.","Family": "you feel responsible for your family's finances.","Self-worth": "a \"bad money week\" feels like a bad you."},"moves": ["If I spend on something I enjoy this week, then I'll not re-check it that night.","If I'm about to say no to a plan because of cost, then I'll suggest a cheaper version instead.","If I review my money, then I'll do it once this week at a set time, not every night."]},{"n": 29,"stem": "Ji Earth","name": "The One Who Says Yes Before Thinking","zhStem": "己土","zhName": "还没想就先答应的人","line": "The \"yes\" leaves your mouth before you've checked your week. Being agreeable is why people love working with you — used one notch too much, your week belongs to everyone but you.","zhLine": "你还没看自己的行程，\"好\"就已经说出口了。好说话是大家喜欢和你共事的原因——只是用多了一点，你的一周就属于所有人，唯独不属于你。","inner": "I said I'd do it. Again.","strength": "You're helpful and responsive. People feel supported by you.","stuck": {"Work": "you accept every request on WhatsApp, even at night.","Money": "you agree to group spending you didn't plan for.","Love": "you say yes to plans you're too tired for, then feel flat.","Family": "your parents' requests come before your own plans by default.","Self-worth": "saying no feels like being a bad person."},"moves": ["If someone asks me for something after work hours, then I'll reply \"I'll check tomorrow\" instead of \"okay\".","If I've said yes to three new things this week, then I'll say \"not this time\" to the fourth.","If I feel a quick \"yes\" coming, then I'll take one breath and look at my calendar first."]},{"n": 30,"stem": "Ji Earth","name": "The One Who Overthinks the Small Choices","zhStem": "己土","zhName": "小事也想很久的人","line": "You can spend 20 minutes choosing lunch and a week replying to one message. Your thoughtfulness comes from caring about doing it right — used one notch too much, small choices take the energy big ones need.","zhLine": "选午餐你能想20分钟，回一条信息能拖一个星期。你的周到来自想把事情做好的心——只是用多了一点，小选择就用掉了大事需要的力气。","inner": "Either is fine, and I still can't decide.","strength": "You consider other people and the details. Your choices are rarely careless.","stuck": {"Work": "drafts sit unsent while you check them again.","Money": "you compare options so long that you miss the deal or the date.","Love": "you overthink texts and second-guess your feelings.","Family": "you ask your parents to help decide things you could decide alone.","Self-worth": "you trust other people's judgement more than yours."},"moves": ["If a choice costs less than $20 or an hour, then I'll decide within one minute.","If I've reread a message twice, then I'll send it.","If I'm about to ask someone to choose for me, then I'll say my first pick out loud first."]},{"n": 31,"stem": "Geng Metal","name": "The One Who Pushes Through Alone","zhStem": "庚金","zhName": "宁愿硬撑也不开口的人","line": "You'd rather push through on your own than admit you need backup. Your toughness has carried you far — used one notch too much, you fight battles that a single message could end.","zhLine": "你宁可自己硬撑，也不愿承认需要帮手。你的硬气带你走了很远——只是用多了一点，你就在打一场一条信息就能结束的仗。","inner": "Asking someone else feels like losing.","strength": "You're strong-willed and fair. You don't quit, and you stand up for your people.","stuck": {"Work": "you compete with peers instead of teaming up.","Money": "you take on costs alone that could be shared.","Love": "arguments become about who's right.","Family": "you clash with the sibling or parent who is most like you.","Self-worth": "asking for help feels like weakness."},"moves": ["If I'm stuck on something for more than an hour, then I'll ask one person for a quick view.","If I'm in a disagreement this week, then I'll ask \"what do you need here?\" before making my point.","If a peer does good work, then I'll tell them, out loud or in writing."]},{"n": 32,"stem": "Geng Metal","name": "The One Who Says It Sharper Than They Mean","zhStem": "庚金","zhName": "话说得比心里更硬的人","line": "You mean \"I care about getting this right\", and it comes out like a blade. Your honesty is clean and brave — used one notch too much, people hear the edge and miss the care.","zhLine": "你心里想的是\"我想把这件事做好\"，说出口却像一把刀。你的直率干净又勇敢——只是用多了一点，别人只听到锋利，听不到在乎。","inner": "I didn't mean it like that, but the room went quiet.","strength": "You cut through confusion. Decisions get made when you speak.","stuck": {"Work": "your feedback is right, but people get defensive.","Money": "quick decisions — quitting, buying, switching — made in one sharp moment.","Love": "in arguments, your words land harder than you wanted.","Family": "your parents call you rude when you meant honest.","Self-worth": "you replay the moment afterwards and feel bad about it."},"moves": ["If I'm about to give feedback, then I'll start with \"I want this to work, so…\".","If I feel heat rising in a conversation, then I'll say \"give me a minute\" and pause.","If I said something sharp this week, then I'll go back and say what I actually meant."]},{"n": 33,"stem": "Geng Metal","name": "The One Who Turns Everything Into a Target","zhStem": "庚金","zhName": "把什么都变成目标的人","line": "Running, saving, even your rest days have a number to hit. Your focus on results gets things done — used one notch too much, nothing gets to be enjoyed for its own sake.","zhLine": "跑步、存钱，连休息日都有要达成的数字。你对结果的专注让事情成真——只是用多了一点，没有一件事能单纯地被享受。","inner": "Done. ...So, what's next?","strength": "You set goals and hit them. You turn ambition into numbers that move.","stuck": {"Work": "one target ends and the next begins with no pause.","Money": "you chase the next figure and rarely spend on joy.","Love": "time together gets judged by how \"productive\" it was.","Family": "you show love by providing results and miss the small talk.","Self-worth": "you feel good only for a moment after each win."},"moves": ["If I hit a goal this week, then I'll take one full evening off before setting the next.","If I'm doing something for fun, then I'll not track or measure it.","If I'm with family, then I'll ask one question that has nothing to do with plans."]},{"n": 34,"stem": "Geng Metal","name": "The One Who Holds Themselves to Iron Rules","zhStem": "庚金","zhName": "用铁规矩要求自己的人","line": "You set rules for yourself that you'd never set for a friend. Your discipline is impressive — used one notch too much, you become the strictest boss you've ever had.","zhLine": "你给自己定的规矩，你绝不会拿来要求朋友。你的自律让人佩服——只是用多了一点，你就成了自己遇过最严厉的老板。","inner": "Resting over something this small? That's soft.","strength": "You're principled and reliable. People trust your word.","stuck": {"Work": "you hold yourself to perfect standards and rarely give yourself credit.","Money": "you follow strict rules even when they no longer fit your life.","Love": "you expect yourself to be the \"right\" partner and hide your rough days.","Family": "you meet every duty, even ones nobody asked you to.","Self-worth": "one broken rule feels like failure."},"moves": ["If I break one of my own rules this week, then I'll say to myself what I'd say to a friend.","If I'm about to skip rest to \"earn\" it, then I'll rest first for 20 minutes.","If I finish a task, then I'll write down one thing I did well before listing what's next."]},{"n": 35,"stem": "Geng Metal","name": "The One Who Needs It to Make Sense First","zhStem": "庚金","zhName": "先要道理才肯行动的人","line": "You need the logic to click before you'll move — even on things you can't fully know yet. Clear thinking is your armour; used one notch too much, you keep waiting for a reason that never comes.","zhLine": "你要先想通道理才肯动——即使是现在还没办法完全知道的事。清晰的思考是你的盔甲，只是用多了一点，你就一直在等一个永远不会来的理由。","inner": "Moving before it makes sense to me feels wrong.","strength": "You think things through and protect people from bad decisions.","stuck": {"Work": "you analyse new ideas until the window closes.","Money": "you stay out of choices you can't fully calculate.","Love": "you try to understand feelings logically, and your partner feels unheard.","Family": "you look to elders for a \"proper\" reason before acting.","Self-worth": "not knowing feels like being wrong."},"moves": ["If I'm 70% sure about a small choice, then I'll go ahead.","If someone shares a feeling, then I'll say \"that makes sense\" before I explain anything.","If I'm stuck waiting for more info, then I'll try a one-week test instead."]},{"n": 36,"stem": "Xin Metal","name": "The One Who Won't Show the Unpolished Part","zhStem": "辛金","zhName": "不肯让人看见没打磨好的一面的人","line": "You only let people see the finished, shining version of you. Your self-respect is real — used one notch too much, no one gets close enough to help with the rough parts.","zhLine": "你只让别人看到打磨好、发着光的你。你的自重是真的——只是用多了一点，就没有人能靠近到可以帮你处理粗糙的那一面。","inner": "I don't want anyone to see the parts that aren't sorted.","strength": "You hold yourself with dignity. People admire how put-together you are.","stuck": {"Work": "you hide problems until you've fixed them alone.","Money": "you keep up a standard of living that's tiring to maintain.","Love": "your partner meets the polished you, not the real one.","Family": "you'd rather struggle than let relatives see you struggle.","Self-worth": "being seen as less than perfect feels unbearable."},"moves": ["If something isn't going well at work, then I'll mention it to one person before it's fixed.","If a friend asks how things are, then I'll share one thing that isn't going well.","If I post or share something this week, then I'll share one unpolished draft or idea with someone I trust."]},{"n": 37,"stem": "Xin Metal","name": "The One Who Edits Until It Shines","zhStem": "辛金","zhName": "改到发光才肯交的人","line": "You redo the slide, the message, the outfit until it shines — and hand it in late, or not at all. Your eye for quality is a rare talent; used one notch too much, \"good\" never feels good enough to share.","zhLine": "简报、信息、穿搭，你都要改到发光——然后晚交，甚至不交。你对品质的眼光很难得，只是用多了一点，\"不错\"永远不够拿出手。","inner": "One more fix and then I'll send it.","strength": "Your work is beautiful and precise. People notice the difference you make.","stuck": {"Work": "deadlines slip because the last 5% takes 50% of your time.","Money": "you buy the \"right\" tools before starting the thing.","Love": "you rehearse what to say so much that the moment passes.","Family": "your parents only see the finished results, never the process.","Self-worth": "you see the flaw first, every time."},"moves": ["If something is 90% done, then I'll send it this week.","If I want to redo something a third time, then I'll ask one person if it's already fine.","If I start a new thing, then I'll begin with what I already have, not new tools."]},{"n": 38,"stem": "Xin Metal","name": "The One Who Has to Earn Every Rest","zhStem": "辛金","zhName": "休息也要先挣来的人","line": "You can only rest after the work is done, the money is in, and the plan is perfect — so you rarely rest. Your drive to deliver is impressive; used one notch too much, you treat rest like a reward you haven't won yet.","zhLine": "你只有在工作做完、钱到账、计划完美之后才肯休息——所以你几乎不休息。你交付成果的劲头让人佩服，只是用多了一点，休息就成了一个你还没赢到的奖品。","inner": "I don't have a good enough reason to rest yet.","strength": "You deliver. People trust you with important things because you take them seriously.","stuck": {"Work": "rest days get filled with \"just one more thing\".","Money": "spending on yourself feels like it needs a reason.","Love": "your partner gets the leftover hours, after work is done.","Family": "you show care through gifts and results, then feel unseen.","Self-worth": "you feel worth it only when you've produced something."},"moves": ["If it's my rest day, then I'll do nothing productive until lunch.","If I'm about to buy something for myself, then I'll not justify it to anyone, including me.","If I'm tired this week, then I'll rest before finishing, not after."]},{"n": 39,"stem": "Xin Metal","name": "The One Who Can't Say No","zhStem": "辛金","zhName": "说不出\"不\"的人","line": "You're not tired because of work. You're tired because you never say no — your sense of responsibility, used one notch too much.","zhLine": "你累，不是因为工作。是因为你从来不说\"不\"——你的责任感，只是用多了一点。","inner": "If I say no, they'll be disappointed.","strength": "You're responsible and you care how people feel. People trust you with what matters.","stuck": {"Work": "you take every extra task and stay late to finish them well.","Money": "you agree to costs (gifts, group plans, family requests) you didn't plan for.","Love": "you say yes to keep the peace, then feel distant.","Family": "your parents' expectations decide big things — the job, the flat, the timing.","Self-worth": "you feel okay only when no one is disappointed in you."},"moves": ["If someone asks me for something this week, then I'll reply \"can I get back to you on Friday?\" to one of them.","If I feel guilty after saying no, then I'll remind myself the guilt means I'm practising, not failing.","If my parents bring up a big decision, then I'll ask for a set date to talk it through instead of agreeing on the spot."]},{"n": 40,"stem": "Xin Metal","name": "The One Who Waits to Be Told They're Good Enough","zhStem": "辛金","zhName": "等别人说\"够好了\"的人","line": "You're already good enough — you're just waiting for someone to say it first. Your humility and wish to learn are lovely; used one notch too much, you hand the judgement of your worth to other people.","zhLine": "你其实已经够好了——只是在等别人先说出来。你的谦虚和好学很可爱，只是用多了一点，你就把评价自己的权利交给了别人。","inner": "I can't feel sure until someone tells me it's okay.","strength": "You keep learning and improving. Mentors love working with you.","stuck": {"Work": "you collect certificates and wait for someone to notice you're ready.","Money": "you follow advice rather than trusting your own research.","Love": "you need reassurance often and feel bad for asking.","Family": "your parents' approval still decides how you feel about your choices.","Self-worth": "praise lifts you for a day; criticism stays for weeks."},"moves": ["If I finish something I'm proud of, then I'll say so to myself before anyone else does.","If I'm waiting for approval this week, then I'll go ahead on one small thing without it.","If someone gives me feedback, then I'll write down one thing they said that was positive."]},{"n": 41,"stem": "Ren Water","name": "The One Who Leaves Before It Gets Heavy","zhStem": "壬水","zhName": "还没变重就先走的人","line": "You keep moving, so nothing gets heavy enough to hold you down — including the people who'd like to stay close. Your freedom is your gift; used one notch too much, you leave before anyone can really know you.","zhLine": "你一直在流动，所以没有什么重到能留住你——包括那些想靠近你的人。自由是你的天赋，只是用多了一点，别人还来不及真正认识你，你就走了。","inner": "Before it gets deep, I want to move on.","strength": "You're independent and brave. You go where others hesitate.","stuck": {"Work": "you switch roles before you've built the depth that gets you promoted.","Money": "you spend on new experiences and peers' plans before you save.","Love": "when it gets serious, you feel the urge to move.","Family": "you keep a distance that feels safe but lonely.","Self-worth": "you feel free, but not always grounded."},"moves": ["If I feel the urge to leave a conversation that's getting deep, then I'll stay five more minutes.","If I want to start something new this week, then I'll give one more week to what I'm already doing.","If I think of a friend I've drifted from, then I'll send them a message today."]},{"n": 42,"stem": "Ren Water","name": "The One With Ten Ideas and No Finish Line","zhStem": "壬水","zhName": "十个点子、没有终点线的人","line": "You have ten great ideas before lunch and finish none of them by Friday. Your creativity is a flood of gifts — used one notch too much, everything starts and nothing lands.","zhLine": "午饭前你就有十个好点子，到星期五一个也没完成。你的创意像洪水一样涌出来——只是用多了一点，什么都开始了，什么都没落地。","inner": "This time, this is the one.","strength": "You see possibilities everywhere. Teams move faster with your ideas.","stuck": {"Work": "your desk is full of half-finished projects.","Money": "you spend on starter kits and courses for the next idea.","Love": "you get bored with routine and look for new excitement.","Family": "your parents worry you haven't \"settled\".","Self-worth": "you feel talented but unfinished."},"moves": ["If I get a new idea this week, then I'll write it in one note and not start it.","If I have three open projects, then I'll pick one to finish this month.","If I finish something, then I'll tell one person before starting the next."]},{"n": 43,"stem": "Ren Water","name": "The One Chasing the Next Opening","zhStem": "壬水","zhName": "一直追下一个机会的人","line": "You can spot an opportunity from across the room — and you're already reaching for the next one. Your sense for openings is sharp; used one notch too much, you never stay long enough to collect what you planted.","zhLine": "你隔着整个房间就能看到机会——而你已经伸手去抓下一个了。你对机会的嗅觉很敏锐，只是用多了一点，你从来没留下来等到自己种下的收成。","inner": "There might be something better than this.","strength": "You're quick to see value and you connect people and deals easily.","stuck": {"Work": "you switch for a better offer before your current role pays off.","Money": "money moves fast in and out; little stays.","Love": "you keep one eye on what else might be out there.","Family": "your family isn't sure what you actually do, because it keeps changing.","Self-worth": "you feel good chasing, less sure once you arrive."},"moves": ["If a new offer catches my eye this week, then I'll wait seven days before replying.","If money comes in this week, then I'll move a fixed share into savings the same day.","If I'm with someone, then I'll stay fully present for one whole meal."]},{"n": 44,"stem": "Ren Water","name": "The One Who Keeps the Peace by Holding It In","zhStem": "壬水","zhName": "为了和气全憋着的人","line": "You have a river of thoughts and you keep it inside the banks so nobody gets wet. Your self-control keeps the peace — used one notch too much, the pressure builds with nowhere to go.","zhLine": "你心里有一整条河的想法，却把它们都收在堤里，免得弄湿任何人。你的克制维持了和气——只是用多了一点，压力越积越高，没有出口。","inner": "Saying it will only make things messy. So I swallow it.","strength": "You can work within tough structures and keep calm in rigid places.","stuck": {"Work": "you go along with rules that don't make sense and say nothing.","Money": "you stay in a stable job even when a better path is clear.","Love": "you hold in frustration until one day it spills over.","Family": "you keep your real plans to yourself to avoid argument.","Self-worth": "you feel your ideas don't count unless someone gives permission."},"moves": ["If I disagree with something in a meeting, then I'll say one sentence about it.","If I feel pressure building, then I'll write it out for 10 minutes that night.","If my family asks about my plans, then I'll share one plan I've kept to myself."]},{"n": 45,"stem": "Ren Water","name": "The One Who Researches Instead of Starting","zhStem": "壬水","zhName": "一直查资料、迟迟不开始的人","line": "You've read everything about it — and still haven't started. Your hunger to understand is deep; used one notch too much, learning becomes the place you hide from doing.","zhLine": "关于它的资料你全看过了——却还没开始。你求知的渴望很深，只是用多了一点，学习就成了你躲开行动的地方。","inner": "Let me look into it a bit more before I start.","strength": "You learn quickly and widely. You often know more than the people in charge.","stuck": {"Work": "you prepare for the role you want instead of applying.","Money": "you study the market and leave your money idle.","Love": "you read about relationships more than you talk to your partner.","Family": "you live by your parents' advice even when you know more.","Self-worth": "you feel you're always one course away from ready."},"moves": ["If I've watched three videos on something, then I'll try it for 15 minutes the same day.","If I'm about to buy a course this week, then I'll first finish one free lesson I already have.","If I have a question for my partner or family, then I'll ask them instead of searching it."]},{"n": 46,"stem": "Gui Water","name": "The One Who Says \"I'm Fine\" First","zhStem": "癸水","zhName": "总先说\"我没事\"的人","line": "You say \"I'm fine\" before anyone finishes asking. Your quiet strength is beautiful — used one notch too much, the people who love you don't know when you need them.","zhLine": "别人还没问完，你就先说\"我没事\"。你安静的坚强很美——只是用多了一点，爱你的人就不知道你什么时候需要他们。","inner": "I don't want them to worry. I'll handle it myself.","strength": "You're resilient and self-contained. You handle hard things gracefully.","stuck": {"Work": "you don't flag problems early, so they grow quietly.","Money": "you handle money worries alone and don't talk about them.","Love": "your partner feels shut out at times.","Family": "your parents think you're always okay.","Self-worth": "needing someone feels like a burden on them."},"moves": ["If someone asks how I am this week, then I'll give one honest detail.","If something is bothering me for two days, then I'll tell one person about it.","If I feel like pulling back from a friend, then I'll send a short message instead of disappearing."]},{"n": 47,"stem": "Gui Water","name": "The One Who Pours Out Until Empty","zhStem": "癸水","zhName": "倒到自己见底的人","line": "You give your attention, your ideas, your feelings — until the cup is empty. Your generosity of spirit makes people feel understood; used one notch too much, there's nothing left for you at the end of the day.","zhLine": "你把注意力、想法、感情都倒给别人——直到杯子空了。你心灵上的大方让人觉得被理解，只是用多了一点，一天结束时就什么都没留给自己。","inner": "After listening to everyone, there was nothing left for me.","strength": "You listen deeply and create with feeling. People open up to you.","stuck": {"Work": "you spend energy on other people's problems and fall behind on your own.","Money": "you spend to comfort yourself after long days of giving.","Love": "you give more than you ask for, then feel unseen.","Family": "you're the emotional listener for everyone at home.","Self-worth": "you feel valued for what you give, not for who you are."},"moves": ["If someone starts venting late at night, then I'll say \"can we talk tomorrow?\" once this week.","If I've had a heavy day, then I'll take 20 minutes alone before helping anyone else.","If I want to create something, then I'll do it for myself first, not to share."]},{"n": 48,"stem": "Gui Water","name": "The One Who Quietly Keeps Everything Running","zhStem": "癸水","zhName": "默默让一切运转的人","line": "The bills are paid, the plans are made, the gaps are filled — and no one knows it was you. Your quiet effectiveness is a gift; used one notch too much, your work becomes invisible, even to you.","zhLine": "账单付了、计划排好了、漏洞补上了——却没人知道是你做的。你安静的能干是天赋，只是用多了一点，你的付出就变得看不见，连你自己都看不见。","inner": "No one needs to notice. ...But I wish someone would, a little.","strength": "You make things work without fuss. Teams and families run because of you.","stuck": {"Work": "your contributions go unnoticed at review time.","Money": "you take on shared costs quietly.","Love": "you do a lot for your partner and don't say what you need back.","Family": "you manage family logistics behind the scenes.","Self-worth": "you wonder if anyone would notice if you stopped."},"moves": ["If I finish something important at work, then I'll mention it to my manager this week.","If I pay for something shared, then I'll ask for the split that day.","If I do something for someone, then I'll also say one thing I'd like in return."]},{"n": 49,"stem": "Gui Water","name": "The One Who Absorbs Everyone's Weather","zhStem": "癸水","zhName": "吸收所有人情绪的人","line": "When someone around you is upset, you feel it before they say a word — and you carry it home. Your sensitivity is a rare gift; used one notch too much, other people's storms become your weather.","zhLine": "身边的人一不开心，你在他们开口前就感觉到了——还把它带回家。你的敏感是难得的天赋，只是用多了一点，别人的风暴就成了你的天气。","inner": "They seemed upset. Was it me?","strength": "You read people and situations accurately. You often know what's needed before anyone says it.","stuck": {"Work": "one cold message from your boss can shape your whole day.","Money": "you spend to smooth over tension — gifts, treats, paying first.","Love": "you adjust to your partner's mood and lose track of your own.","Family": "you keep the home calm by managing everyone's feelings.","Self-worth": "you feel okay only when everyone around you is okay."},"moves": ["If someone seems upset, then I'll ask \"is it about me?\" instead of guessing.","If I come home carrying someone else's mood, then I'll change clothes and say \"that's theirs, not mine\".","If I notice my mood dropping because of someone else's, then I'll step away for 10 minutes."]},{"n": 50,"stem": "Gui Water","name": "The One Who Waits for a Sign","zhStem": "癸水","zhName": "等一个信号的人","line": "You trust your intuition — so you wait for it to send a clear sign before you move. That inner sense is real; used one notch too much, you wait for a sign that only comes once you start.","zhLine": "你相信自己的直觉——所以总要等它给出清楚的信号才肯动。这份内在的感觉是真的，只是用多了一点，你等的那个信号，其实要你先动了才会出现。","inner": "Somehow it doesn't feel like the time yet.","strength": "You sense things others don't. When you trust yourself and act, you're often right.","stuck": {"Work": "you hold back on changes until it \"feels right\", which can take years.","Money": "decisions wait until you feel completely sure.","Love": "you wait for the other person to show clear signs before you open up.","Family": "you rely on your parents' sense of what's right more than your own.","Self-worth": "you doubt your instincts unless someone confirms them."},"moves": ["If I've had the same gut feeling for a week, then I'll take one small step towards it.","If I'm waiting for a sign this week, then I'll decide that today's thought is the sign.","If I want to tell someone something, then I'll say it within the next day."]}];
if(typeof module!=="undefined") module.exports.TYPES=TYPES;
